// Focused teaching examples, deliberately separate from checkpoint solutions.
// Every object is serializable so these aids can travel through static page props.
const asm = (source, filename = 'concept.asm') => ({ language: 'asm', source, filename });
const fact = (label, value) => ({ label, value });
const node = (id, title, subtitle, explanation, facts = [], source) => ({
  id, title, subtitle, explanation, facts,
  ...(source ? { code: asm(source) } : {}),
});
const visual = (kind, title, intro, nodes, caption, source, connections) => ({
  kind, title, intro, nodes, caption,
  ...(source ? { sample: asm(source) } : {}),
  ...(connections ? { connections } : {}),
});
const trace = (title, intro, nodes, caption, source) => visual(
  'trace', title, intro, nodes, caption, source,
  nodes.slice(1).map((item, index) => ({ from: nodes[index].id, to: item.id, label: 'then' })),
);

